nd stick to the DW netiquette policy on our channel: https://p.dw.com/p/MF1G","thumbnail":"https://i.ytimg.com/vi/p49QRxO_n2c/maxresdefault.jpg","category":"Documentaries","city":"","country":"","channel":"DW Documentary","channelTitle":"DW Documentary","channelId":"UCW39zufHfsuGgpLviKh297Q","badge":"DOCUMENTARY","publishedAt":"2024-09-19T16:00:55Z","viewCount":3158993,"durationSeconds":2547,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"DOCUMENTARIES"}}',1);
