h DW Documentary. Subscribe to DW Documentary: https://www.youtube.com/channel/UCW39... For more documentaries visit: http://www.dw.com/en/tv/docfilm/s-3610 Instagram https://www.instagram.com/dwdocumentary/ Facebook: https://www.facebook.com/dw.stories DW netiquette policy: https://p.dw.com/p/MF1G","thumbnail":"https://i.ytimg.com/vi/cYP_wMJsgyg/maxresdefault.jpg","category":"Documentaries","city":"","country":"","channel":"DW Documentary","channelTitle":"DW Documentary","channelId":"UCW39zufHfsuGgpLviKh297Q","badge":"DOCUMENTARY","publishedAt":"2018-12-12T19:00:03Z","viewCount":2740592,"durationSeconds":2551,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"DOCUMENTARIES"}}',1);
